const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const seattle = ee.Geometry.Point([-122.3321, 47.6062]);
    const startDate = '2021-11-01';
    const endDate = '2021-12-01';

    // 2. Data Acquisition & Check
    const datasetId = 'ECMWF/ERA5-LAND/HOURLY';
    let collection = ee.ImageCollection(datasetId)
        .filterBounds(seattle)
        .filterDate(startDate, endDate)
        .select('total_precipitation');

    const imageCount = collection.size().getInfo();
    if (imageCount === 0) {
        console.log("No images found for the specified period.");
        console.log("A: No");
        return;
    }

    // 3. Processing
    // Sum all hourly precipitation images to get a single image of total precipitation for the month.
    // The unit is meters.
    const totalPrecipitationMeters = collection.sum();

    // 4. Calculation
    // Extract the precipitation value at the Seattle point.
    const scale = 1000; // Scale appropriate for ERA5-Land (~11km resolution)
    const stats = totalPrecipitationMeters.reduceRegion({
        reducer: ee.Reducer.first(),
        geometry: seattle,
        scale: scale,
        maxPixels: 1e9
    });

    const precipValueMeters = stats.get('total_precipitation').getInfo();

    // 5. Validation & Final Answer
    if (precipValueMeters === null || typeof precipValueMeters === 'undefined') {
        console.log("Could not calculate precipitation value.");
        console.log("C3: Calculation Failure");
        return;
    }

    // Convert meters to centimeters
    const precipValueCm = precipValueMeters * 100;

    console.log(`Dataset: ${datasetId}`);
    console.log(`Image count for Nov 2021: ${imageCount}`);
    console.log(`Total precipitation (m): ${precipValueMeters.toFixed(4)}`);
    console.log(`Total precipitation (cm): ${precipValueCm.toFixed(2)}`);

    if (precipValueCm < 20) {
        console.log("A: Yes");
    } else {
        console.log("B: No");
    }
}

async function initEE() {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
}

initEE().catch(err => {
    console.error(err);
    console.log("D: If image, collection, or band names are incorrect, syntax or method error, wrong method, or memory issue, etc.");
});
